mapper.update:
UPDATE report_checklist_items rci
INNER JOIN report_checklists rc ON rc.report_checklist_id = rci.report_checklist_id
SET rci.is_checked = #{checked}, rci.modified_at = CURRENT_TIMESTAMP
WHERE rc.report_checklist_id = #{reportChecklistId}
AND rc.account_id = #{accountId}
AND rci.checklist_item_id = #{checklistItemId}

UPDATE report_checklist_items rci
INNER JOIN report_checklists rc ON rc.report_checklist_id = rci.report_checklist_id
SET rci.is_checked = TRUE, rci.modified_at = CURRENT_TIMESTAMP
WHERE rc.report_checklist_id = #{reportChecklistId}
AND rc.account_id = #{accountId}
AND rci.checklist_item_id = #{checklistItemId}

UPDATE report_checklist_items rci
INNER JOIN report_checklists rc ON rc.report_checklist_id = rci.report_checklist_id
SET rci.is_checked = FALSE, rci.modified_at = CURRENT_TIMESTAMP
WHERE rc.report_checklist_id = #{reportChecklistId}
AND rc.account_id = #{accountId}

